-- Колода «Выше среднего B2» в общей базе слов. Напечатано vocabulario/deck2sql.py
-- Источник: vocabulario/baralho-completo-B2.json, карточек: 497.
-- Без темы (398): a habitação, satisfazer, elevado, a etapa, o nativo, a troça, ajustar, coerente, concreto, o destaque, o destinatário, a evolução, fluentemente, isolado, a serra, o acento, agitar, contestar, expor, implicar, o índice, o lazer, a negociação, a proximidade, recorrer, relatar, a repetição, a substituição, a tendência, o trajeto, tranquilizar, abordar, acusar, a admiração, o anexo, a angústia, autorizar, a beira-mar, o calão, a camada …
-- Повторное выполнение безопасно: содержимое обновляется, прогресс людей не трогается.

begin;

values ('b2', 'Выше среднего B2', '497 карточек уровня B2 с примерами и заметками', 'B2', 'B2', 40)
on conflict (id) do update set name = excluded.name, descr = excluded.descr,
  level_from = excluded.level_from, level_to = excluded.level_to, sort = excluded.sort;

on conflict (id) do update set deck_id = excluded.deck_id, word = excluded.word,
  pos = excluded.pos, ru = excluded.ru, ex = excluded.ex, exru = excluded.exru,
  note = excluded.note, level = excluded.level, tema = excluded.tema, sort = excluded.sort;

on conflict (id) do update set deck_id = excluded.deck_id, word = excluded.word,
  pos = excluded.pos, ru = excluded.ru, ex = excluded.ex, exru = excluded.exru,
  note = excluded.note, level = excluded.level, tema = excluded.tema, sort = excluded.sort;

on conflict (id) do update set deck_id = excluded.deck_id, word = excluded.word,
  pos = excluded.pos, ru = excluded.ru, ex = excluded.ex, exru = excluded.exru,
  note = excluded.note, level = excluded.level, tema = excluded.tema, sort = excluded.sort;

delete from public.pt_words
 where deck_id = 'b2' and updated_at < now();

commit;

select count(*) as слов, count(*) filter (where level = '') as без_уровня,
       count(distinct tema) as тем
  from public.pt_words where deck_id = 'b2';
